// Valores anteriores del sensor
let temperatura = context.get("temperatura") ?? 23;
let humedad = context.get("humedad") ?? 50;
let luminosidad = context.get("luminosidad") ?? 250;

// Variaciones peque?as para simular un sensor real
temperatura += (Math.random() - 0.5) * 0.6;
humedad += (Math.random() - 0.5) * 2;
luminosidad += (Math.random() - 0.5) * 20;

// L?mites razonables de simulaci?n
temperatura = Math.max(18, Math.min(30, temperatura));
humedad = Math.max(30, Math.min(70, humedad));
luminosidad = Math.max(100, Math.min(500, luminosidad));

// Guardar valores para la siguiente lectura
context.set("temperatura", temperatura);
context.set("humedad", humedad);
context.set("luminosidad", luminosidad);

// Presencia simulada
const presencia = Math.random() > 0.5;

// C?digo de la exhibici?n y sensor
const exhibicionCodigo = "EXP-001";
const sensorCodigo = "SENSOR-001";

// Construir mensaje
msg.topic = `museo/exhibiciones/${exhibicionCodigo}/sensor`;

msg.payload = {
    sensorCodigo: sensorCodigo,
    exhibicionCodigo: exhibicionCodigo,
    presencia: presencia,
    temperatura: Number(temperatura.toFixed(2)),
    humedad: Number(humedad.toFixed(2)),
    luminosidad: Math.round(luminosidad),
    timestamp: new Date().toISOString()
};

return msg;

const timestamp = new Date().toISOString();

function uuid() { return crypto.randomUUID(); }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function variar(v, delta, min, max) { return clamp(v + (Math.random() * 2 - 1) * delta, min, max); }
function red(v, d) { const f = Math.pow(10, d); return Math.round(v * f) / f; }

// 6 sensores ambientales (uno por sala). La identidad es SOLO sensorCodigo:
// el backend resuelve la sala real desde el sensor (los ids no son estables).
// Sin salaId en el payload.
const sensoresAmbientales = [
    { sensorCodigo: 'SENSOR-AMBIENTAL-001', temp: 22.0, hum: 50, lum: 300 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-002', temp: 23.0, hum: 55, lum: 250 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-003', temp: 21.0, hum: 60, lum: 200 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-004', temp: 20.0, hum: 50, lum: 280 },
    // Sala 5 (Escultura y retratos): ambiente mas fresco y luz contenida.
    { sensorCodigo: 'SENSOR-AMBIENTAL-005', temp: 20.5, hum: 45, lum: 150 },
    // Sala 6 (Civilizaciones antiguas): ligeramente mas calida.
    { sensorCodigo: 'SENSOR-AMBIENTAL-006', temp: 21.5, hum: 48, lum: 180 }
];

// 12 sensores de presencia (uno por exhibicion), identificados SOLO por codigo.
// Sin exhibicionId en el payload: el backend resuelve la exhibicion del sensor.
const sensoresPresencia = [
    'SENSOR-PRESENCIA-001',
    'SENSOR-PRESENCIA-002',
    'SENSOR-PRESENCIA-003',
    'SENSOR-PRESENCIA-004',
    'SENSOR-PRESENCIA-005',
    'SENSOR-PRESENCIA-006',
    'SENSOR-PRESENCIA-007',
    'SENSOR-PRESENCIA-008',
    'SENSOR-PRESENCIA-009',
    'SENSOR-PRESENCIA-010',
    'SENSOR-PRESENCIA-011',
    'SENSOR-PRESENCIA-012'
];

// Rangos configurables de simulacion
const LIM = {
    temperatura: { min: 18, max: 30, delta: 0.3 },
    humedad:     { min: 30, max: 70, delta: 1 },
    luminosidad: { min: 100, max: 500, delta: 10 }
};
const P_CAMBIO_PRESENCIA = 0.2;

const msgs = [];

// --- Sensores ambientales (6) ---
for (const s of sensoresAmbientales) {
    const kT = 'temp_' + s.sensorCodigo;
    const kH = 'hum_' + s.sensorCodigo;
    const kL = 'lum_' + s.sensorCodigo;
    const t = red(variar(context.get(kT) ?? s.temp, LIM.temperatura.delta, LIM.temperatura.min, LIM.temperatura.max), 2);
    const h = red(variar(context.get(kH) ?? s.hum, LIM.humedad.delta, LIM.humedad.min, LIM.humedad.max), 2);
    const l = red(variar(context.get(kL) ?? s.lum, LIM.luminosidad.delta, LIM.luminosidad.min, LIM.luminosidad.max), 2);
    context.set(kT, t); context.set(kH, h); context.set(kL, l);
    msgs.push({
        topic: 'museo/sensores/ambiental',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: s.sensorCodigo,
            temperatura: t,
            humedad: h,
            luminosidad: l,
            timestamp: timestamp
        }
    });
}

// --- Sensores de presencia (12): el estado persiste entre ciclos ---
for (const sensorCodigo of sensoresPresencia) {
    const k = 'presencia_' + sensorCodigo;
    let estado = context.get(k);
    if (typeof estado !== 'boolean') {
        estado = Math.random() < 0.3; // ocupacion inicial variada
    } else if (Math.random() < P_CAMBIO_PRESENCIA) {
        estado = !estado; // entrada/salida ocasional
    }
    context.set(k, estado);
    msgs.push({
        topic: 'museo/sensores/presencia',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: sensorCodigo,
            presencia: estado,
            timestamp: timestamp
        }
    });
}

node.status({ fill: 'blue', shape: 'dot', text: msgs.length + ' mensajes' });
return [msgs];
